class ConfigElementoSalarialSituacionServicio extends BaseConfigElementoSalarialSituacionServicio {

    /**
     * Obtener un listado de los datos de los elementos salariales al cargo.
     * 
     * @param int       $inicio Inicio de la busqueda.
     * @param int       $limite Limite maximo de la busqueda.
     * @return array    Listado de los datos de los elementos salariales al cargo.
     */
    public static function obtenerListadoElementosSalariales($inicio = 0, $limite = 10) {
        //Devolviendo el listado de elementos salariales al cargo en forma de arreglo.
        return Doctrine_Query::create()
                ->from('ConfigElementoSalarialSituacionServicio')
                ->limit($limite)
                ->offset($inicio)
                ->fetchArray();
    }

    /**
     * Obtener la cantidad total de tipos de nómina.
     * 
     * @return int      Cantidad total de tipos de nómina.
     */
    public static function obtenerCantidadTotalElementosSalariales() {

        //Devolviendo la cantidad total de tipos de nómina.
        return Doctrine_Query::create()->select('COUNT(idelementosalarialsituacionservicio) AS cantidad')
                        ->from('ConfigElementoSalarialSituacionServicio')
                        ->fetchOne()
                        ->cantidad;
    }

    /**
     * Obtener el tipo de nómina dado el identificador.
     * 
     * @param int $idtiponomina    Identificador del tipo de nómina.
     * @return NomTipoNomina      Objeto tipo de nómina (clase del dominio).
     */
    public static function obtenerObjElementoSalarialDadoId($idelementosalarial) {
        return Doctrine::getTable('ConfigElementoSalarialSituacionServicio')->find($idelementosalarial);
    }
    
    public static function obtenerCantidadTotalElemSalPersona($idpersona) {

        //Devolviendo la cantidad total de los salarios especificos.
        return Doctrine_Query::create()->select('COUNT(idelementosalarialsituacionservicio) AS cantidad')
                        ->from('ConfigElementoSalarialSituacionServicio')
                        ->where('idpersona = ?', array($idpersona))
                        ->fetchOne()
                        ->cantidad;
   }
   
   public static function obtenerElemSalPersona($idpersona) {

        //Devolviendo la cantidad total de los salarios especificos.
        return Doctrine_Query::create()
                        ->from('ConfigElementoSalarialSituacionServicio')
                        ->where('idpersona = ?', array($idpersona))
                        ->fetchArray();
   }
   
   public static function obtenerElemSalPersonaCargoOcupado($idpersona, $idcargoocupado) {

        //Devolviendo la cantidad total de los salarios especificos.
        return Doctrine_Query::create()
                        ->from('ConfigElementoSalarialSituacionServicio')
                        ->where('idpersona = ? and idcargoocupado = ?', array($idpersona, $idcargoocupado))
                        ->fetchArray();
   }
   
   public static function existeConfElementoSalarialPersonaCargoOcupado($idpersona, $idcargoocupado) {
        //Devolviendo la cantidad total de los salarios especificos.
        $query = new Doctrine_Query ();
        $result = $query->from('ConfigElementoSalarialSituacionServicio p')
                ->where("p.idpersona=? and p.idcargoocupado=?", array($idpersona, $idcargoocupado))
                ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
                ->execute();
          if(count($result)){
		   return true;	
	         }else{
		   return false;
		 }
     }
   
   public static function existeConfElementoSalarialCargoOcupado($idcargoocupado) {
        //Devolviendo la cantidad total de los salarios especificos.
        $query = new Doctrine_Query ();
        $result = $query->from('ConfigElementoSalarialSituacionServicio p')
                ->where("p.idcargoocupado=?", array($idcargoocupado))
                ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
                ->execute();
          if(count($result)){
		   return 1;	
	         }else{
		   return 2;
		 }
     }
     
